from taf.sw.dcap.rd.services.custom_traces.custom_base import CustomTraceBase
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.trace_profile_tracer import TraceProfileTracer
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.provided_trace import ProvidedTrace

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CustomVcuTraceProfile(CustomTraceBase):
    def __init__(self, requirements, **kwargs):
        super(CustomVcuTraceProfile, self).__init__()
        self.custom_trace_profile = self._generate_custom_trace_profile(requirements=requirements,
                                                                        trace_type='VCU',
                                                                        **kwargs)

    def get_l2_5g(self, included_trace_mode, **kwargs):
        provided_traces = []
        provided_traces += [ProvidedTrace(
            snapshot=False,
            trace="l2Vcu")]
        return [TraceProfileTracer(
            provided_traces=provided_traces,
            params=[
                {
                    "values": included_trace_mode,
                    "name": "l2TraceMode"
                }
            ], type='VCU',
            name="L2", id="l2Vcu")]

    @staticmethod
    def custom_vcu_syslog(custom_vcu_dict, **kwargs):
        vcu_custom_profile = 'syslogVcu'
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vcu_dict[vcu_custom_profile].get('tracer_id'),
                type='VCU')],
            params=CustomTraceBase.custom_syslog_vran(kwargs),
            type='VCU',
            name=custom_vcu_dict[vcu_custom_profile].get('name'),
            id=custom_vcu_dict[vcu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vcu_control_plane_interface(custom_vcu_dict, **kwargs):
        vcu_custom_profile = "controlPlane5gVcu"
        control_plane_interface = kwargs.get('vcu_control_plane_interface', 'auto')
        monitoring_profiles = kwargs.get('vcu_monitoring_profiles', 'vcu-full-call-scenarios')
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vcu_dict[vcu_custom_profile].get('tracer_id'),
                type="VCU")],
            params=CustomTraceBase.custom_control_plane_interface(control_plane_interface=control_plane_interface,
                                                                  monitoring_profiles=monitoring_profiles),
            type="VCU",
            name=custom_vcu_dict[vcu_custom_profile].get('name'),
            id=custom_vcu_dict[vcu_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_vcu_screl(custom_vcu_dict, **kwargs):
        vcu_custom_profile = "screlVcu"
        kwargs['screl_coverage_vcu'] = kwargs.get('screl_coverage_vcu') or "default"
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_vcu_dict[vcu_custom_profile].get('tracer_id'),
                type="VCU")],
            params=[
                {
                    "name": "screlCoverage",
                    "values": [
                        kwargs['screl_coverage_vcu']
                    ]
                }], type="VCU",
            name=custom_vcu_dict[vcu_custom_profile].get('name'),
            id=custom_vcu_dict[vcu_custom_profile].get('tracer_id'))

    def custom_tracers(self, custom_profile, **kwargs):
        if custom_profile == 'flowTracerVcu':
            logger.warning("flowTracerVcu is deprecated, please use controlPlane5gVcu instead.")
        custom_vcu_dict = {'snapshotVcu': {'name': 'Snapshot', 'tracer_id': 'snapshotVcu'},
                           'tracerVcu': {'name': 'Cell Trace', 'tracer_id': 'ntracerVcu'},
                           'flowTracerVcu': {'name': 'Control Plane', 'tracer_id': 'flowTracerVcu'},
                           'controlPlane5gVcu': {'name': 'Control Plane', 'tracer_id': 'controlPlane5gVcu'},
                           'syslogVcu': {'name': 'Syslog', 'tracer_id': 'syslogVcu'},
                           'screlVcu': {'name': 'System critical event logs (SCREL)', 'tracer_id': 'screlVcu'}}
        custom_vcu_profile_option = []

        profile_functions = {
            'syslogVcu': self.custom_vcu_syslog,
            'controlPlane5gVcu': self.custom_vcu_control_plane_interface,
            'screlVcu': self.custom_vcu_screl
        }

        if custom_profile in profile_functions:
            custom_vcu_profile_option.append(profile_functions[custom_profile](
                custom_vcu_dict=custom_vcu_dict,
                **kwargs))
        elif custom_profile in custom_vcu_dict:
            custom_vcu_profile_option.append(TraceProfileTracer(
                provided_traces=[ProvidedTrace(
                    snapshot=False,
                    trace=custom_vcu_dict[custom_profile].get('tracer_id'),
                    type='VCU')],
                params=[], type='VCU',
                name=custom_vcu_dict[custom_profile].get('name'),
                id=custom_vcu_dict[custom_profile].get('tracer_id')))
        return custom_vcu_profile_option
